    66|/** Normalize a phone to E.164 (+1...). Accepts "561-644-3503" or "+15616443503". */
    67|export function normalizePhoneToE164(input: string): string {
    68|  const raw = (input || '').trim();
    69|  if (!raw) return '';
    70|  const digits = raw.replace(/\D/g, '');
    71|  if (!digits) return '';
    72|  // US/CA: 10 digits → prepend +1
    73|  if (digits.length === 10) return `+1${digits}`;
    74|  if (digits.length === 11 && digits.startsWith('1')) return `+${digits}`;
    75|  if (raw.startsWith('+')) return `+${digits}`;
    76|  return `+${digits}`;
