    activeAgents: agentKind.filter((a) => a.activation_status === 'ACTIVE').length,
    agents: agentKind.map((a) => ({
      agentId: a.factory_agent_id,
      name: a.name,
      activationStatus: a.activation_status,
      qaStatus: a.qa_status,
    })),
  };
}

